export function t(key, vars = {}) {
  const entry = C[key];
  if (!entry) throw new Error(`No copy for ${key}`);
  return entry.text.replace(/\{(\w+)\}/g, (_, k) => {
    if (!(k in vars)) throw new Error(`Copy ${key} needs ${k}`);
    return String(vars[k]);
  });
}

export function source(key) {
  return C[key].source;
}
